def transform(grid):
    divider = next(r for r, row in enumerate(grid) if all(v == 5 for v in row))

    def longest(rows, color):
        best = 0
        for c in range(len(grid[0])):
            run = 0
            for row in rows:
                if row[c] == color:
                    run += 1
                    best = max(best, run)
                else:
                    run = 0
        return best

    colors = {v for row in grid for v in row if v not in (0, 5)}
    top, bottom = grid[:divider], grid[divider + 1:]
    color = max(colors, key=lambda v: longest(bottom, v) - longest(top, v))
    return [[color, color], [color, color]]
